char* escape_xpath(const char* input) {
    // Simple escape function for XPath special characters
    size_t len = strlen(input);
    char* escaped = (char*)malloc(len * 2 + 1); // worst case: every character needs escaping
    if (!escaped) return NULL;

    char* p = escaped;
    for (size_t i = 0; i < len; i++) {
        switch (input[i]) {
            case '\'':
                *p++ = '\\'; // escape single quote
                *p++ = '\'';
                break;
            case '\"':
                *p++ = '\\'; // escape double quote
                *p++ = '\"';
                break;
            case '\\':
                *p++ = '\\'; // escape backslash
                *p++ = '\\';
                break;
            default:
                *p++ = input[i];
                break;
        }
    }
    *p = '\0';
    return escaped;
}

