        }

        hash_len = EVP_MD_size(EVP_sha256());
        if (hash_len <= 0) {
            throw std::runtime_error("Invalid hash size");
        }

        hash.resize(hash_len);
        hashed_passwords.emplace_back(std::move(hash), std::move(salt));
    }

    return hashed_passwords;
}

